// Shared physical artwork. All coordinates refer to the terminal contract in model.mjs.
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const label=(x,y,v,cls='micro')=>`<text x="${x}" y="${y}" class="${cls}" text-anchor="middle">${esc(v)}</text>`;
const poles=(y,screws)=>Array.from({length:6},(_,i)=>`<circle class="screw" cx="${16+i*25}" cy="${y}" r="6"/>${screws?`<path class="screw-slot" d="M${12+i*25} ${y}h8"/>`:''}`).join('');
export const visuals={
 pot:c=>`<path class="board" d="M-52 116h104v23H-52z"/><circle class="metal" cy="82" r="54"/><circle class="rim" cy="82" r="48"/><path class="rim" d="M-43 55l6 4M43 55l-6 4M-44 107l6-3M44 107l-6-3"/><path class="metal" d="M-48 123h12v25h-12zM-6 129h12v19H-6zM36 123h12v25H36z"/><ellipse class="case-pad" cx="0" cy="82" rx="13" ry="9"/>${label(0,58,c.value.startsWith('CTS')?'CTS':'REAR VIEW')}${label(0,115,c.value.replace('CTS ',''),'part-value')}${label(-26,164,'3 / CW','terminal-label')}${label(13,184,'2 / WIPER','terminal-label')}${label(56,164,'1 / CCW','terminal-label')}`,
 humbucker:c=>`<path class="pickup-base" d="M-9 22h-8v28h8v43h-8v28h17v7h156v-7h16V93h-9V50h9V22h-16V4H0v18z"/><rect class="bobbin-dark" x="0" y="10" width="156" height="49" rx="9"/><rect class="bobbin-light" x="0" y="68" width="156" height="49" rx="9"/>${poles(34,false)}${poles(93,true)}${label(78,52,'SLUG COIL','coil-label light-label')}${label(78,111,'SCREW COIL','coil-label')}<path class="pickup-cable" d="M158 94H175Q180 94 180 103V118"/>`,
 singlecoil:c=>`<path class="pickup-base" d="M8 18h140l12 18v40l-12 18H8L-4 76V36z"/><rect class="bobbin-light" x="0" y="27" width="156" height="58" rx="26"/>${poles(56,false)}<path class="pickup-cable" d="M155 70h24v47"/>`,
 capacitor:c=>{const style=c.physicalStyle||'orangeDrop';return `<path class="lead" d="M-46 0h20m52 0h20"/>${style==='disc'?'<circle class="disc-body" r="20"/>':style==='film'?'<rect class="film-body" x="-29" y="-15" width="58" height="30" rx="2"/>':'<path class="cap-body" d="M-28-7Q-28-17-17-17H17Q28-17 28-7V7Q28 17 17 17H-17Q-28 17-28 7z"/>'}${label(0,-28,c.value,'part-value')}${c.productMark?label(0,34,c.productMark):''}`;},
 resistor:c=>`<path class="lead" d="M-46 0h18m56 0h18"/><path class="resistor-body" d="M-28-7l6-5h44l6 5V7l-6 5h-44l-6-5z"/>${label(0,-23,c.value,'part-value')}`,
 toggle:c=>`<path class="metal" d="M-16 3h32v32h-32z"/><rect class="board" x="-60" y="33" width="120" height="53" rx="2"/><path class="rim" d="M-48 45h96M-48 70h96"/><path class="metal" d="M-66 76h12v39h-12zM-26 76h12v39h-12zM14 76h12v39H14zM54 76h12v39H54zM-6-6h12v15H-6z"/>${label(0,58,'SOLDER SIDE')}${label(-60,136,'N','terminal-label')}${label(-20,136,'OUT N','terminal-label')}${label(26,154,'OUT B','terminal-label')}${label(65,136,'B','terminal-label')}`,
 jack:c=>`<circle class="board" cy="48" r="33"/><circle class="metal" cy="48" r="25"/><circle class="jack-hole" cy="48" r="14"/><path class="metal" d="M16 38l15-26 18 1 4 10-25 22M-19 48l-32-2-2 16 32 1"/><path class="rim" d="M25 39l8 28-18 13"/>${label(47,-2,'TIP / SIGNAL','terminal-label')}${label(-44,88,'SLEEVE / GROUND','terminal-label')}${label(0,112,'SOLDER SIDE')}`,
 ground:c=>`<path class="ground-symbol" d="M0 0v12m-16 0h32m-25 7h18m-13 7h8"/>`
};
visuals.pushpull=c=>visuals.pot(c)+`<rect class="metal" x="-37" y="213" width="74" height="85" rx="2"/><path class="board" d="M-33 218h66v70h-66z"/>${Object.entries(c.terminals).filter(([id])=>id.startsWith('switch')).map(([id,t])=>`<rect class="metal" x="${t.x-5}" y="${t.y-5}" width="10" height="10"/>${label(t.x+(t.x<0?-21:21),t.y+4,id.replace('switch',''),'terminal-label')}`).join('')}${label(0,320,'DPDT / SOLDER SIDE')}`;
visuals.p90=c=>`<rect class="bobbin-dark" x="0" y="10" width="156" height="100" rx="9"/>${poles(60,true)}<path class="pickup-cable" d="M156 85h24v33"/>`;
// A conventional 3-way and 5-way blade both have two poles, each with common + 3 throws.
// Position/contact behaviour belongs to the circuit definition, not to this visual.
const legacyBlade=c=>{const superSwitch=c.type==='superswitch',height=superSwitch?454:133;return `<rect class="metal" x="-19" y="-36" width="217" height="${height+35}" rx="3"/><rect class="board" x="-12" y="-14" width="197" height="${height}" rx="3"/><path class="metal" d="M86 32h20v33H86z"/><path class="rim" d="M35 52h119"/><circle class="screw" cx="96" cy="52" r="8"/><path class="lead" d="M200-60v24h-8"/>${Object.entries(c.terminals).filter(([k])=>k!=='ground').map(([key,t])=>`<path class="metal ${key.endsWith('C')?'common-lug':''}" d="M${t.x-7} ${t.y-7}h14v17h-14z"/>${label(t.x,t.y+29,key,'terminal-label')}`).join('')}${label(95,83,superSwitch?'4-POLE SUPER SWITCH':'STANDARD 2-POLE BLADE')}${label(95,99,'SOLDER SIDE · C = COMMON')}`;};
const blade=c=>{if(c.type==='superswitch')return legacyBlade(c);const five=c.type==='blade5'||c.label.includes('5-WAY');return `<g class="blade-hardware" data-blade-operation="${five?5:3}"><path class="blade-frame" d="M-18-32Q-18-40-8-40H170l23 18v144l-23 22H-8q-10 0-10-10z"/><path class="blade-wafer" d="M-8-8Q-8-16 0-16h127q10 0 10 10v122q0 10-10 10H0q-8 0-8-8z"/><path class="blade-wafer-seam" d="M-5 48h139M-5 61h139"/><circle class="screw" cx="170" cy="-15" r="6"/><circle class="screw" cx="170" cy="125" r="6"/><path class="rim" d="M166-15h8M166 125h8"/><path class="blade-lever" d="M157 19h17v63l-8 12-9-12z"/><path class="blade-lever-slot" d="M165 25v50"/><path class="lead" d="M200-60v27l-11 12"/>${Object.entries(c.terminals).filter(([k])=>k!=='ground').map(([key,t])=>`<path class="blade-lug ${key.endsWith('C')?'common-lug':''}" d="M${t.x-9} ${t.y-5}q0-7 9-7t9 7v12q0 6-9 6t-9-6z"/><ellipse class="lug-hole" cx="${t.x}" cy="${t.y}" rx="4" ry="2.5"/>${label(t.x,t.y+(key.startsWith('A')?22:-16),key,'blade-terminal-label')}`).join('')}${label(166,108,five?'5-WAY':'3-WAY','blade-caption')}${label(65,57,'SOLDER SIDE','blade-orientation')}${label(65,82,'C: COMMON','blade-caption')}</g>`;};
visuals.blade=blade;visuals.blade3=blade;visuals.blade5=blade;visuals.superswitch=blade;
visuals.network=c=>`<path class="lead" d="M-46 0h14m64 0h14"/><rect class="board" x="-32" y="-20" width="64" height="40"/>${label(0,4,c.value)}`;

// Shared physical pickup glyphs for descriptive configuration; no circuit or contact logic.
export function pickupLayoutArtwork(pickups){return `<svg class="pickup-layout-art" viewBox="0 0 ${pickups.length*180} 140" focusable="false" aria-hidden="true"><style>.pickup-base{fill:#777;stroke:#aaa}.bobbin-dark{fill:#333;stroke:#9a8156}.bobbin-light{fill:#b9a373;stroke:#9a8156}.screw{fill:#ddd;stroke:#777}.screw-slot{stroke:#555}.pickup-cable,.coil-label,.light-label{display:none}text{fill:#ddd;font:12px sans-serif}</style>${pickups.map((p,n)=>`<g transform="translate(${n*180+12} 3)">${(p.type==='single'?visuals.singlecoil:visuals.humbucker)({})}<text x="78" y="135" text-anchor="middle">${esc(p.position)} · ${p.type==='single'?'S':'H'}</text></g>`).join('')}</svg>`;}
